-- INSERT de elementos deportivos reales extraídos de ABRs050_ FORMATO CRD F(1).xlsx
-- Se usó DESCRIPCIÓN como nombre/descripcion y la columna N° como cantidad.
-- Si ya tenías el seed demo, esta línea lo desactiva para que no se mezclen elementos de prueba con inventario real.
BEGIN;
UPDATE "elementos_deportivos" SET "activo" = false, "actualizadoEn" = NOW() WHERE "codigo" IN ('BAL-FUT-001', 'BAL-VOL-001', 'RAQ-TEN-001', 'CON-001', 'PET-001', 'PLA-001', 'ARO-001', 'VOL-BAD-001');

ON CONFLICT ("codigo") DO UPDATE SET
  "nombre" = EXCLUDED."nombre",
  "descripcion" = EXCLUDED."descripcion",
  "marca" = EXCLUDED."marca",
  "color" = EXCLUDED."color",
  "categoria" = EXCLUDED."categoria",
  "cantidadTotal" = EXCLUDED."cantidadTotal",
  "cantidadDisponible" = EXCLUDED."cantidadDisponible",
  "activo" = true,
  "icono" = EXCLUDED."icono",
  "actualizadoEn" = NOW();
COMMIT;